var n=`0948-katsu-curry`;var i=`world-0948`;var a=`JP`;var r=`east-asia`;var o=4;var s=83;var l={en:`Katsu Curry`,ua:`Кацу-карі`};var d={en:`Katsu Curry is a Japan dish made with pork loin, all-purpose flour, chicken egg, panko breadcrumbs. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Кацу-карі, страва кухні країни Японія. Основні складники: свиняча корейка, пшеничне борошно універсальне, куряче яйце, панко. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:12,i:[[`pork-loin`,690,`g`],[`all-purpose-flour`,95,`g`],[`chicken-egg`,2,`pcs`],[`panko-breadcrumbs`,210,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 17 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 17 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:17,i:[[`canola-oil`,700,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,200,`g`],[`carrot`,230,`g`],[`potato`,280,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 18 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 18 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:18,i:[[`japanese-curry-roux`,135,`g`],[`water`,760,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 23 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 23 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:23,i:[[`jasmine-rice`,410,`g`],[`water`,770,`ml`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:4,i:[]}];var g={slug:n,id:i,country:`JP`,region:r,servings:4,minutes:83,title:l,text:d,steps:u};export{a as country,g as default,i as id,s as minutes,r as region,o as servings,n as slug,u as steps,d as text,l as title};